import {regionProfile} from './region-map.js';
import {decodeScriptText} from './script-engine.js';
import {encodedText} from './item-maker.js';
const STOCK='3d0c79f1627022e18765766f6cb5ea067f6b5bf7dca115552189ad65a5c3a8ac';
const START=['Pokédex','Pokémon','Bag','Player','Save','Options','Exit','Retire','Link player'];
const OPTIONS=['Text speed','Battle scene','Battle style','Sound','Button mode','Frame','Cancel','Slow speed','Medium speed','Fast speed','Battle scene on','Battle scene off','Shift style','Set style','Mono sound','Stereo sound','Help buttons','L/R buttons','L = A buttons'];
function readFixedEngineTexts(reader,hash){if(regionProfile(hash).engine==='emerald')throw Error('Menu text editing needs an Emerald text adapter.');const stock=hash===STOCK,groups=[{name:'START menu',at:stock?0x3a7344:0x3cb890,stride:8,labels:START},{name:'Options',at:stock?0x3cc314:0x3f0b60,stride:4,labels:OPTIONS}],rows=[];for(const [g,group]of groups.entries())for(const [i,name]of group.labels.entries()){const ref=group.at+i*group.stride,address=reader.u32(ref)-0x08000000;if(address<512||address>=reader.bytes.length)throw Error('The native menu text table failed verification.');if(!g){const fn=reader.u32(ref+4);if(!(fn&1)||fn<0x08000000||fn>=0x0a000000)throw Error('The START menu callback failed verification.');}const text=decodeScriptText(reader.bytes,address).text;if(!text||text.length>100)throw Error('Unsupported native menu label.');rows.push({id:g+':'+i,group:group.name,name,address,reference:ref,text,maxChars:g&&i>=7?6:12});}return rows;}
export function engineTextBytes(row,text){if(typeof text!=='string'||!text.trim()||text.length>row.maxChars||/[\r\n]|\\[npl]|\{(?!PLAYER\})/.test(text))throw Error('Keep this label to '+row.maxChars+' characters and one line.');const tokens=s=>s.match(/\{[^}]+\}/g)||[];if(tokens(text).join()!==tokens(row.text).join())throw Error('Keep the native player-name placeholder.');return encodedText(text);}
export function engineTextWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;let rows,reader,hash;function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');reader=session.reader;hash=session.id;rows=readEngineTexts(reader,hash);api.modal('Native menu text',`<p>Edit the START menu and Options labels. Each edit changes its verified table entry; other uses of the same source text retain their wording.</p>${rows.map(r=>`<button type="button" class="studio-record" data-engine-text="${r.id}"><span><b>${esc(r.group+' · '+r.name)}</b><small>${esc(api.project().textEdits?.[hash]?.['engine:'+r.id]?.text??r.text)}</small></span></button>`).join('')}`,null,'Done');document.querySelectorAll('[data-engine-text]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.engineText)));}
 function edit(row){const prior=api.project().textEdits?.[hash]?.['engine:'+row.id];api.modal(row.group+' · '+row.name,`<label>Label<input id="engineTextValue" maxlength="${row.maxChars}" value="${esc(prior?.text??row.text)}"></label><p>One line, up to ${row.maxChars} characters. Player-name placeholders must remain.</p><p id="engineTextError" role="status"></p><button id="engineTextReset" type="button">Restore source label</button>`,()=>{const text=$('#engineTextValue').value;try{engineTextBytes(row,text);}catch(e){$('#engineTextError').textContent=e.message;return false;}api.change(()=>{api.project().textEdits??={};api.project().textEdits[hash]??={};api.project().textEdits[hash]['engine:'+row.id]={kind:'engine',slotId:row.id,original:row.text,text,references:[row.reference]};});open();},'Save label');$('#engineTextReset').onclick=()=>{api.change(()=>{if(api.project().textEdits?.[hash])delete api.project().textEdits[hash]['engine:'+row.id];});open();};}return{open};}

const menuCache=new WeakMap();
export function readEngineTexts(reader,hash){if(menuCache.has(reader))return menuCache.get(reader);try{const rows=readFixedEngineTexts(reader,hash);menuCache.set(reader,rows);return rows;}catch{}
 const norm=s=>s.toLowerCase().replaceAll('é','e').replace(/[^a-z]/g,''),groups=[{name:'START menu',stride:8,labels:START},{name:'Options',stride:4,labels:OPTIONS}],rows=[];
 for(const[g,group]of groups.entries()){const candidates=[];for(let at=512;at<reader.size-group.labels.length*group.stride;at+=4){const p=reader.ptr(at);if(p<512||p>=reader.size)continue;const first=reader.u8(p);if(first!==0xca&&first!==0xce&&first!==0xda&&first!==0xe8)continue;let good=true;for(let i=0;i<3;i++){const ref=at+i*group.stride,q=reader.ptr(ref);if(!reader.valid(q,1)||!reader.bytes.subarray(q,q+80).includes(255)||norm(decodeScriptText(reader.bytes,q).text)!==norm(group.labels[i])){good=false;break;}}if(good)candidates.push(at);}
  const valid=[];for(const at of candidates)try{const out=[];for(const[i,name]of group.labels.entries()){const ref=at+i*group.stride,address=reader.ptr(ref),text=decodeScriptText(reader.bytes,address).text;if(!reader.valid(address,1)||!text||text.length>100)throw Error('Invalid menu row');if(!g){const fn=reader.u32(ref+4);if(!(fn&1)||!reader.valid(fn-0x08000001,2))throw Error('Invalid menu callback');}out.push({id:g+':'+i,group:group.name,name,address,reference:ref,text,maxChars:g&&i>=7?6:12});}valid.push(out);}catch{}if(valid.length===1)rows.push(...valid[0]);}
 if(!rows.length)throw Error('The opened ROM’s menu label tables could not be uniquely identified. ROM dialogue remains available.');menuCache.set(reader,rows);return rows;
}
